apiChanges:
paths:
  /api/v1/links:
    post:
      requestBody: CreateLinkRequest gains note: { type: [string, 'null'], maxLength: 280 }
  /api/v1/links/{code}/stats.csv:
    get:
      summary: Daily clicks of a link as CSV
      parameters: [code (path), from (query, date), to (query, date)]
      responses:
        '200': { description: 'day,clicks rows', content: { text/csv: {} } }
        '400': { description: invalid range (type /problems/invalid-stats-range) }
        '404': { description: unknown or another key's link (type /problems/link-not-found) }
components:
  schemas:
    LinkResponse: gains note: { type: [string, 'null'] }
